import day from "../assets/wordmark-stacked.svg?raw";
import night from "../assets/wordmark-stacked-dark.svg?raw";

/**
 * The stacked wordmark, inlined so its parts can animate (see .wordmark rules in index.css):
 * the names rise in, the bead drops onto the cursor i, then the cursor blinks.
 * Day and night versions both render; CSS shows the one matching the theme (the night one has a
 * starch cursor so the i stays visible on indigo). Generated by Documents/brand/build.mjs.
 */
export function Wordmark({ className = "" }: { className?: string }) {
  return (
    <div className={`wordmark ${className}`} role="img" aria-label="Mustapha Sulaimon. Akanbi, made on purpose.">
      <div className="wm-day" dangerouslySetInnerHTML={{ __html: day }} />
      <div className="wm-night" dangerouslySetInnerHTML={{ __html: night }} />
    </div>
  );
}
